7	import type { TokenStorage, OAuthCredentials } from './types.js';
8	
9	export abstract class BaseTokenStorage implements TokenStorage {
10	  protected readonly serviceName: string;
11	
12	  constructor(serviceName: string) {
13	    this.serviceName = serviceName;
14	  }
15	
16	  abstract getCredentials(serverName: string): Promise<OAuthCredentials | null>;
17	  abstract setCredentials(credentials: OAuthCredentials): Promise<void>;
18	  abstract deleteCredentials(serverName: string): Promise<void>;
19	  abstract listServers(): Promise<string[]>;
20	  abstract getAllCredentials(): Promise<Map<string, OAuthCredentials>>;
21	  abstract clearAll(): Promise<void>;
22	
23	  protected validateCredentials(credentials: OAuthCredentials): void {
24	    if (!credentials.serverName) {
25	      throw new Error('Server name is required');
26	    }
27	    if (!credentials.token) {
28	      throw new Error('Token is required');
29	    }
30	    if (!credentials.token.accessToken) {
31	      throw new Error('Access token is required');
32	    }
33	    if (!credentials.token.tokenType) {
34	      throw new Error('Token type is required');
35	    }
36	  }
37	
38	  protected isTokenExpired(credentials: OAuthCredentials): boolean {
39	    if (!credentials.token.expiresAt) {
40	      return false;
41	    }
42	    const bufferMs = 5 * 60 * 1000;
43	    return Date.now() > credentials.token.expiresAt - bufferMs;
44	  }
45	
46	  protected sanitizeServerName(serverName: string): string {
47	    return serverName.replace(/[^a-zA-Z0-9-_.]/g, '_');
48	  }
